def traverse(graph, start):
    visited = set()
    def dfs(node):
        if node is None or node in visited:
            return []
        visited.add(node)
        result = [node]
        for neighbor in graph.get(node, []):
            result.extend(dfs(neighbor))
        return result
    return dfs(start)

